/* @lc app=leetcode id=2842 lang=kotlin */ class Solution { fun countKSubsequencesWithMaxBeauty(s: String, k: Int): Int = if (k > 26) 0 else s.groupingBy { it }.eachCount().values.sortedDescending().let { counts -> if (counts.size < k) 0 else counts[k - 1].let { f -> counts.count { it > f }.let { n1 -> counts.count { it == f }.let { n2 -> (k - n1).let { r -> 1_000_000_007L.let { mod -> (counts.filter { it > f }.fold(1L) { acc, i -> (acc * i) % mod } * ((1..r).fold(1L) { acc, i -> acc * (n2 - i + 1) / i } % mod) % mod * (1..r).fold(1L) { acc, _ -> (acc * f) % mod } % mod).toInt() } } } } } } }